gDX(){return"\u0627\u0644\u062a\u0646\u0628\u064a\u0647 \u0645\u064f\u0633\u062c\u064e\u0651\u0644 (\u0628\u062f\u0648\u0646 \u0645\u0648\u0642\u0639). \u0625\u0646 \u0643\u0646\u062a \u0641\u064a \u062e\u0637\u0631 \u0641\u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 112."},
gDS(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0625\u0646\u062a\u0631\u0646\u062a \u0627\u0644\u0622\u0646. \u062a\u0646\u0628\u064a\u0647\u0643 \u0645\u062d\u0641\u0648\u0638 \u0648\u0633\u064a\u064f\u0631\u0633\u064e\u0644 \u0648\u062d\u062f\u0647 \u0639\u0646\u062f\u0645\u0627 \u064a\u0639\u0648\u062f. \u0633\u0644\u0627\u0645\u062a\u0643 \u0623\u0647\u0645 \u0634\u064a\u0621."},
gDM(){return"\u0644\u0645 \u064a\u064f\u0631\u0633\u064e\u0644 \u062a\u0646\u0628\u064a\u0647\u0643 \u0648\u0644\u0645 \u064a\u064f\u062d\u0641\u064e\u0638\u060c \u0648\u0644\u0646 \u064a\u064f\u0631\u0633\u064e\u0644 \u0648\u062d\u062f\u0647. \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 112 \u0627\u0644\u0622\u0646!"},
gDQ(){return"\u0644\u0645 \u064a\u064f\u0631\u0633\u064e\u0644 \u062a\u0646\u0628\u064a\u0647\u0643 \u0628\u0639\u062f\u060c \u0644\u0643\u0646\u0651\u0647 \u0645\u062d\u0641\u0648\u0638. \u0633\u064a\u064f\u0631\u0633\u064e\u0644 \u0648\u062d\u062f\u0647 \u0639\u0646\u062f\u0645\u0627 \u062a\u0639\u0648\u062f \u0627\u0644\u0634\u0628\u0643\u0629."},
gOi(){return"\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0627\u0644\u0622\u0646"},
gDN(){return"\u062c\u0627\u0631\u064d"},
gDt(){return"\u062a\u0645\u062a \u0627\u0644\u0631\u0624\u064a\u0629"},
gDT(){return"\u062a\u0645 \u0627\u0644\u062d\u0644"},
gDA(){return"\u0623\u064f\u0644\u063a\u064a\u062a"},
gDd(){return"\u0644\u0642\u062f \u0631\u0623\u064a\u062a\u0647"},
gE2(){return"\u062a\u0645 \u062a\u062d\u062f\u064a\u062b \u0627\u0644\u062a\u0646\u0628\u064a\u0647"},
gqI(){return"\u0644\u0627 \u064a\u0645\u0643\u0646 \u0625\u064a\u0642\u0627\u0641 \u0647\u0630\u0647 \u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0625\u0644\u0627 \u0645\u0646 \u0642\u0628\u0644 \u0648\u0644\u064a \u0623\u0645\u0631\u0643 \u0627\u0644\u0645\u0633\u0624\u0648\u0644. \u064a\u0645\u0643\u0646\u0643 \u0625\u0639\u0627\u062f\u0629 \u062a\u0641\u0639\u064a\u0644\u0647\u0627 \u0641\u064a \u0623\u064a \u0648\u0642\u062a."},
gJS(){return"\u0644\u062f\u064a\u0651 \u0631\u0645\u0632 \u062f\u0639\u0648\u0629"},
gKz(){return"\u0631\u0645\u0632 \u0627\u0644\u062f\u0639\u0648\u0629"},
gKA(){return"\u0627\u0644\u062f\u0639\u0648\u0629 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d\u0629 \u0623\u0648 \u0645\u0646\u062a\u0647\u064a\u0629 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629."},
gKx(){return"\u0623\u064f\u0631\u0633\u0644 \u0627\u0644\u0637\u0644\u0628 \u2014 \u0639\u0644\u0649 \u0627\u0644\u0634\u062e\u0635 \u0627\u0644\u0645\u062d\u0645\u064a \u0623\u0646 \u064a\u0624\u0643\u0651\u062f\u0643 \u0627\u0644\u0622\u0646."},
gPL(){return"\u0645\u0646\u0632\u0644 \u0627\u0644\u0648\u0627\u0644\u062f \u0627\u0644\u0622\u062e\u0631"},
gPI(){return"\u0627\u0644\u0623\u062c\u062f\u0627\u062f"},
gPH(){return"\u0645\u0646\u0632\u0644 \u0635\u062f\u064a\u0642"},
