gPC(){return"\u0645\u0634\u062a\u0631\u0643\u0629"},
gPB(){return"\u0639\u0644\u0649 \u0623\u064a \u0623\u0634\u062e\u0627\u0635 \u0645\u062d\u0645\u064a\u064a\u0646 \u062a\u0646\u0637\u0628\u0642 \u0647\u0630\u0647 \u0627\u0644\u0645\u0646\u0637\u0642\u0629\u061f"},
gPS(){return"\u0625\u0632\u0627\u0644\u0629 \u0644\u062f\u0649 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0644\u0645\u062d\u0645\u064a\u064a\u0646"},
gAb(){return"\u062a\u0645 \u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0645\u0624\u0642\u062a\u064b\u0627"},
gLY(){return"\u0633\u062c\u0644\u0651\u064a"},
gKF(){return"\u0633\u062c\u0644 \u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u062e\u0627\u0635 \u0628\u064a"},
gKE(){return"\u0644\u0627 \u0634\u064a\u0621 \u062d\u062a\u0649 \u0627\u0644\u0622\u0646. \u064a\u0628\u0642\u0649 \u0647\u0630\u0627 \u0627\u0644\u0633\u062c\u0644 \u0639\u0644\u0649 \u0647\u0627\u062a\u0641\u0643 \u0623\u0646\u062a: \u0644\u0627 \u064a\u0645\u0643\u0646 \u0644\u0623\u062d\u062f \u063a\u064a\u0631\u0643 \u0631\u0624\u064a\u062a\u0647."},
