gIG(){return"\u062a\u0648\u0642\u0641\u062a \u0627\u0644\u062d\u0645\u0627\u064a\u0629"},
gIE(){return"\u0645\u063a\u0627\u062f\u0631\u0629 \u0645\u0646\u0637\u0642\u0629 \u0622\u0645\u0646\u0629"},
gID(){return"\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0645\u0646\u0637\u0642\u0629 \u0622\u0645\u0646\u0629"},
gxK(){return"\u0631\u064f\u0641\u0636 \u0627\u0644\u062a\u0633\u062c\u064a\u0644 (\u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0645\u0648\u0642\u0648\u0641\u0629)"},
gIJ(){return"\u0627\u0644\u0628\u0637\u0627\u0631\u064a\u0629 \u0645\u0646\u062e\u0641\u0636\u0629"},
gIO(){return"\u0641\u064f\u0642\u062f\u062a \u0627\u0644\u0625\u0634\u0627\u0631\u0629"},
gIP(){return"\u0639\u0627\u062f\u062a \u0627\u0644\u0625\u0634\u0627\u0631\u0629"},
