gqD(){return"\u0641\u064f\u0642\u062f\u062a \u0627\u0644\u0625\u0634\u0627\u0631\u0629"},
gNF(){return"\u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0639\u0645\u0631 \u0627\u0644\u0634\u062e\u0635 \u0627\u0644\u062d\u0627\u0645\u064a 15 \u0639\u0627\u0645\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644."},
gOe(){return"\u064a\u0648\u062c\u062f \u0628\u0627\u0644\u0641\u0639\u0644 \u0637\u0644\u0628 \u0644\u0647\u0630\u0627 \u0627\u0644\u0634\u062e\u0635 \u0627\u0644\u0645\u062d\u0645\u064a."},
