gv_(){return"\u0623\u0642\u0631\u0628 \u0646\u0642\u0637\u0629 \u0627\u0633\u062a\u0642\u0628\u0627\u0644"},
gAP(){return"\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u0629 \u0627\u0644\u0645\u062e\u062a\u0635\u0629 \u063a\u064a\u0631 \u0645\u0646\u0634\u0648\u0631\u0629: \u0625\u0644\u064a\u0643 \u0623\u0642\u0631\u0628 \u0646\u0642\u0637\u0629 \u0627\u0633\u062a\u0642\u0628\u0627\u0644."},
guZ(){return"\u0627\u0644\u0634\u0631\u0637\u0629 \u0627\u0644\u0648\u0637\u0646\u064a\u0629"},
guY(){return"\u0627\u0644\u062f\u0631\u0643 \u0627\u0644\u0648\u0637\u0646\u064a"},
gAW(){return"\u0627\u0644\u0627\u062a\u062c\u0627\u0647\u0627\u062a"},
