gAG(){return"\u0627\u0644\u0635\u0645 / \u0636\u0639\u0627\u0641 \u0627\u0644\u0633\u0645\u0639 \u2014 114"},
gAO(){return"\u0644\u062a\u0642\u062f\u064a\u0645 \u0634\u0643\u0648\u0649\u060c \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u062a\u0648\u062c\u0647 \u0625\u0644\u0649 \u0623\u064a \u0645\u0631\u0643\u0632 \u0634\u0631\u0637\u0629 \u0623\u0648 \u062f\u0631\u0643. \u064a\u062c\u0628 \u0639\u0644\u0649 \u0627\u0644\u062e\u062f\u0645\u0629 \u0627\u0633\u062a\u0644\u0627\u0645 \u0627\u0644\u0634\u0643\u0648\u0649 \u0648\u0625\u062d\u0627\u0644\u062a\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u0627\u0642\u062a\u0636\u0627\u0621 (\u0627\u0644\u0645\u0627\u062f\u0629 15-3 \u0645\u0646 \u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062c\u0632\u0627\u0626\u064a\u0629)."},
gAQ(){return"\u0644\u0645 \u064a\u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 \u062e\u062f\u0645\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u0639\u0646\u0648\u0627\u0646."},
gAL(){return"\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f. \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0643\u062a\u0627\u0628\u0629."},
AJ(a){return"\u0639\u0644\u0649 \u0628\u064f\u0639\u062f "+a+" \u0643\u0645"},
gAN(){return"\u0627\u0639\u062b\u0631 \u0639\u0644\u0649 \u062e\u062f\u0645\u0629 \u0627\u0644\u0634\u0631\u0637\u0629/\u0627\u0644\u062f\u0631\u0643 \u0644\u0645\u0646\u0632\u0644\u0643 \u0648\u0623\u0642\u0631\u0628 \u0646\u0642\u0637\u0629 \u0627\u0633\u062a\u0642\u0628\u0627\u0644. \u0644\u0627 \u064a\u063a\u0646\u064a \u0639\u0646 \u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0637\u0648\u0627\u0631\u0626."},
