gCS(){return"\u062a\u0645\u062a \u0625\u0636\u0627\u0641\u0629 \u0635\u0648\u0631\u0629 \u0627\u0644\u0645\u0631\u0643\u0628\u0629"},
gCR(){return"\u062a\u0639\u0630\u0651\u0631\u062a \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0635\u0648\u0631\u0629"},
gtb(){return"\u0631\u0633\u0627\u0644\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
